export type LeadMascotProps = Omit<SVGProps<SVGSVGElement>, "viewBox" | "children"> & {
  pose?: MascotPose;

  decor?: boolean;

  label?: string | null;
};

export function LeadMascot({
  pose = "neutral",
  decor = false,
  label = null,
  ...props
}: LeadMascotProps) {
  const art = POSES[pose];
  const box = decor ? MASCOT_VIEWBOX.full : MASCOT_VIEWBOX.tight;
  const [x, y] = decor ? art.full : art.tight;

  return (
    <svg
      viewBox={`${x} ${y} ${box.w} ${box.h}`}
      xmlns="http://www.w3.org/2000/svg"
      preserveAspectRatio="xMidYMax meet"
      role={label ? "img" : undefined}
      aria-label={label ?? undefined}
      aria-hidden={label ? undefined : true}
      focusable="false"
      {...props}
    >
      {decor && art.decor.map(([fill, d], i) => <path key={`d${i}`} fill={fill} d={d} />)}
      {art.body.map(([fill, d], i) => (
        <path key={i} fill={fill} d={d} />
      ))}
    </svg>
  );
}
